    /**
 * <div id="mongodb-driver-manager.getservers" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::getServers</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::getServers</span> — <span class="dc-title">Return the servers to which this manager is connected</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.getservers-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::getServers</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span>   instances to which this manager is connected.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Since the driver connects to the database lazily, this method may return an    empty <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> if called before executing an operation on the    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span>.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.getservers-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.getservers-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span>   instances to which this manager is connected.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.getservers-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-manager.getservers-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Manager::getServers()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// The driver connects to the database server lazily, so Manager::getServers()<br> * may initially return an empty array. <br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getServers</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$command </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">([</span><span style="color: #DD0000">'ping' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">'db'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getServers</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(0)&nbsp;{<br>}<br>array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(MongoDB\Driver\Server)#3&nbsp;(10)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["host"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(9)&nbsp;"localhost"<br>&nbsp;&nbsp;&nbsp;&nbsp;["port"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(27017)<br>&nbsp;&nbsp;&nbsp;&nbsp;["type"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;&nbsp;&nbsp;["is_primary"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;&nbsp;&nbsp;["is_secondary"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;&nbsp;&nbsp;["is_arbiter"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;&nbsp;&nbsp;["is_hidden"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;&nbsp;&nbsp;["is_passive"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;&nbsp;&nbsp;["last_hello_response"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;array(8)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["isWritablePrimary"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["maxBsonObjectSize"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(16777216)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["maxMessageSizeBytes"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(48000000)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["maxWriteBatchSize"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(1000)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["localTime"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\UTCDateTime)#4&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["milliseconds"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(1447267964517)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["maxWireVersion"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["minWireVersion"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["ok"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;float(1)<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["round_trip_time"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(554)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.getservers-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::selectServer()} - Select a server matching a read preference</span></li>  </ul> </div></div>
