    final public function getServers(): array {}

    /**
 * <div id="mongodb-driver-manager.getwriteconcern" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::getWriteConcern</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::getWriteConcern</span> — <span class="dc-title">Return the WriteConcern for the Manager</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.getwriteconcern-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::getWriteConcern</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="type MongoDB\Driver\WriteConcern" style="color:#EAB766">MongoDB\Driver\WriteConcern</a></span></div>  <p class="simpara">   Returns the <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span> for the   Manager, which is derived from its URI options. This is the default write   concern for writes and commands executed on the Manager.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.getwriteconcern-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.getwriteconcern-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span> for the Manager.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.getwriteconcern-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-manager.getwriteconcern-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Manager::getWriteConcern()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcern</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017/?w=majority&amp;wtimeoutMS=2000'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcern</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\Driver\WriteConcern)#2&nbsp;(0)&nbsp;{<br>}<br>object(MongoDB\Driver\WriteConcern)#1&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;["w"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"majority"<br>&nbsp;&nbsp;["wtimeout"]=&gt;<br>&nbsp;&nbsp;int(2000)<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.getwriteconcern-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::__construct()} - Create new MongoDB Manager</span></li>  </ul> </div></div>
