     * @link https://php.net/manual/zh/mongodb-driver-manager.getwriteconcern.php
     * @throws InvalidArgumentException on argument parsing errors.
     * @return WriteConcern
     */
    final public function getWriteConcern(): WriteConcern {}

    /**
 * <div id="mongodb-driver-manager.selectserver" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::selectServer</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::selectServer</span> — <span class="dc-title">Select a server matching a read preference</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.selectserver-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::selectServer</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="type MongoDB\Driver\ReadPreference" style="color:#EAB766">MongoDB\Driver\ReadPreference</a></span></span> <span class="parameter" style="color:#3A95FF">\$readPreference</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="type MongoDB\Driver\Server" style="color:#EAB766">MongoDB\Driver\Server</a></span></div>  <p class="simpara">   Selects a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> matching   <span class="parameter" style="color:#3A95FF">readPreference</span>. If   <span class="parameter" style="color:#3A95FF">readPreference</span> is <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> or omitted, the primary   server will be selected by default. This may be used to preselect a server in   order to perform version checking before executing an operation.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    Unlike <span class="function">{@link MongoDB\Driver\Manager::getServers()}</span>, this method    will initialize database connections and perform server discovery if    necessary. See the    <a href="https://github.com/mongodb/specifications/blob/master/source/server-selection/server-selection.md#single-threaded-server-selection" class="link external">»&nbsp;Server Selection Specification</a>    for additional information.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.selectserver-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">readPreference</span> (<span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span>)</dt>    <dd>     <span class="simpara">      The read preference to use for selecting a server. If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> or omitted,      the primary server will be selected by default.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.selectserver-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span> matching the read   preference.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.selectserver-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if a server matching the read preference could not be found.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-manager.selectserver-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.11.0</td>      <td>       The <span class="parameter" style="color:#3A95FF">readPreference</span> is now optional. If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> or       omitted, the primary server will be selected by default.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.selectserver-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-server.php" class="classname">MongoDB\Driver\Server</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::getServers()} - Return the servers to which this manager is connected</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/server-selection/server-selection.md" class="link external">»&nbsp;Server Selection Specification</a></li>  </ul> </div></div>
 * 
     * Preselect a MongoDB node based on provided readPreference. This can be useful to guarantee a command runs on a specific server when operating in a mixed version cluster.
     * https://secure.php.net/manual/en/mongodb-driver-manager.selectserver.php
     * @param ReadPreference|null $readPreference Optionally, a MongoDB\Driver\ReadPreference to route the command to. If none given, defaults to the Read Preferences set by the MongoDB Connection URI.
     * @throws InvalidArgumentException on argument parsing errors.
     * @throws ConnectionException if connection to the server fails (for reasons other than authentication).
     * @throws AuthenticationException if authentication is needed and fails.
     * @throws RuntimeException if a server matching the read preference could not be found.
     * @return Server
     */
    final public function selectServer(?ReadPreference $readPreference = null) {}

    /**
 * <div id="mongodb-driver-manager.startsession" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::startSession</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::startSession</span> — <span class="dc-title">Start a new client session for use with this client</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.startsession-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::startSession</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="type MongoDB\Driver\Session" style="color:#EAB766">MongoDB\Driver\Session</a></span></div>  <p class="simpara">   Creates a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span> for the given   options. The session may then be specified when executing commands, queries,   and write operations.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    A <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span> can only be used with the    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-manager.php" class="classname">MongoDB\Driver\Manager</a></span> from which it was created.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.startsession-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>          <th>Default</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>causalConsistency</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           <span class="simpara">            Configure causal consistency in a session. If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, each operation            in the session will be causally ordered after the previous read or            write operation. Set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> to disable causal consistency.           </span>           <span class="simpara">            See            <a href="https://www.mongodb.com/docs/manual/core/read-isolation-consistency-recency/#causal-consistency" class="link external">»&nbsp;Causal Consistency</a>            in the MongoDB manual for more information.           </span>          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong></td>         </tr>         <tr>          <td>defaultTransactionOptions</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            Default options to apply to newly created transactions. These            options are used unless they are overridden when a transaction is            started with different value for each option.           </span>           <p class="para">            </p><table class="doctable table">             <caption><strong>options</strong></caption>                           <thead>               <tr>                <th>Option</th>                <th>Type</th>                <th>Description</th>               </tr>              </thead>              <tbody class="tbody">                        <tr>          <td>maxCommitTimeMS</td>          <td>integer</td>          <td>           <span class="simpara">            The maximum amount of time in milliseconds to allow a single            <span class="literal">commitTransaction</span> command to run.           </span>           <span class="simpara">            If specified, <span class="literal">maxCommitTimeMS</span> must be a signed            32-bit integer greater than or equal to zero.           </span>          </td>         </tr>                        <tr>          <td>readConcern</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readconcern.php" class="classname">MongoDB\Driver\ReadConcern</a></span></td>          <td>           <span class="simpara">            A read concern to apply to the operation.           </span>           <span class="simpara">            This option is available in MongoDB 3.2+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>                        <tr>          <td>readPreference</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span></td>          <td>           <span class="simpara">            A read preference to use for selecting a server for the operation.           </span>          </td>         </tr>                        <tr>          <td>writeConcern</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></td>          <td>           <span class="simpara">            A write concern to apply to the operation.           </span>          </td>         </tr>              </tbody>                         </table>                      <span class="simpara">            This option is available in MongoDB 4.0+.           </span>          </td>          <td><span class="literal">[]</span></td>         </tr>         <tr>          <td>snapshot</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           <span class="simpara">            Configure snapshot reads in a session. If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, a timestamp will            be obtained from the first supported read operation in the session            (i.e. <span class="literal">find</span>, <span class="literal">aggregate</span>, or            unsharded <span class="literal">distinct</span>). Subsequent read operations            within the session will then utilize a <span class="literal">"snapshot"</span>            read concern level to read majority-committed data from that            timestamp. Set to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> to disable snapshot reads.           </span>           <span class="simpara">            Snapshot reads require MongoDB 5.0+ and cannot be used with causal            consistency, transactions, or write operations. If            <span class="literal">"snapshot"</span> is <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>,            <span class="literal">"causalConsistency"</span> will default to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.           </span>           <span class="simpara">            See            <a href="https://www.mongodb.com/docs/manual/reference/read-concern-snapshot/#read-concern-and-atclustertime" class="link external">»&nbsp;Read Concern "snapshot"</a>            in the MongoDB manual for more information.           </span>          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.startsession-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span>.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.startsession-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if the <span class="literal">"causalConsistency"</span> and <span class="literal">"snapshot"</span> options are both <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the session could not be created (e.g. libmongoc does not support crypto).</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-manager.startsession-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.11.0</td>      <td>       <span class="simpara">        The <span class="literal">"snapshot"</span> option was added.       </span>      </td>     </tr>     <tr>      <td>PECL mongodb 1.6.0</td>      <td>       <span class="simpara">        The <span class="literal">"maxCommitTimeMS"</span> option was added to        <span class="literal">"defaultTransactionOptions"</span>.       </span>      </td>     </tr>     <tr>      <td>PECL mongodb 1.5.0</td>      <td>       <span class="simpara">        The <span class="literal">"defaultTransactionOptions"</span> option was added.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.startsession-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span></li>   <li><a href="https://www.mongodb.com/docs/manual/core/read-isolation-consistency-recency/#causal-consistency" class="link external">»&nbsp;Causal Consistency</a> in the MongoDB manual</li>  </ul> </div></div>
 * 
     * Start a new client session for use with this client
     * @param array|null $options
     * @return \MongoDB\Driver\Session
     * @throws \MongoDB\Driver\Exception\InvalidArgumentException On argument parsing errors
     * @throws \MongoDB\Driver\Exception\RuntimeException If the session could not be created (e.g. libmongoc does not support crypto).
     * @link https://secure.php.net/manual/en/mongodb-driver-manager.startsession.php
     * @since 1.4.0
     */
    final public function startSession(?array $options = null) {}

    /**
 * <div id="mongodb-driver-manager.addsubscriber" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::addSubscriber</h1>  <p class="verinfo">(mongodb &gt;=1.10.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::addSubscriber</span> — <span class="dc-title">Registers a monitoring event subscriber with this Manager</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.addsubscriber-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::addSubscriber</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="type MongoDB\Driver\Monitoring\Subscriber" style="color:#EAB766">MongoDB\Driver\Monitoring\Subscriber</a></span> <span class="parameter" style="color:#3A95FF">\$subscriber</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Registers a monitoring event subscriber with this Manager. The subscriber   will be notified of all events for this Manager.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    If <span class="parameter" style="color:#3A95FF">subscriber</span> is already registered with this    Manager, this function is a no-op. If <span class="parameter" style="color:#3A95FF">subscriber</span> is    also registered globally, it will still only be notified once of each event    for this Manager.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.addsubscriber-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">subscriber</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="type MongoDB\Driver\Monitoring\Subscriber" style="color:#EAB766">MongoDB\Driver\Monitoring\Subscriber</a></span>)</dt>    <dd>     <span class="simpara">      A monitoring event subscriber to register with this Manager.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.addsubscriber-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.addsubscriber-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>    Throws    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if    <span class="parameter" style="color:#3A95FF">subscriber</span> is a    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-logsubscriber.php" class="classname">MongoDB\Driver\Monitoring\LogSubscriber</a></span>, since    loggers can only be registered globally.   </li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.addsubscriber-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::removeSubscriber()} - Unregisters a monitoring event subscriber with this Manager</span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="interfacename">MongoDB\Driver\Monitoring\Subscriber</a></span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsubscriber.php" class="interfacename">MongoDB\Driver\Monitoring\CommandSubscriber</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\addSubscriber()} - Registers a monitoring event subscriber globally</span></li>   <li><a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a></li>  </ul> </div></div>
 * 
     * Registers a monitoring event subscriber with this Manager
     * @link https://www.php.net/manual/en/mongodb-driver-manager.addsubscriber.php
     * @since 1.10.0
     */
    final public function addSubscriber(Subscriber $subscriber): void {}

    /**
 * <div id="mongodb-driver-manager.removesubscriber" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Manager::removeSubscriber</h1>  <p class="verinfo">(mongodb &gt;=1.10.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Manager::removeSubscriber</span> — <span class="dc-title">Unregisters a monitoring event subscriber with this Manager</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-manager.removesubscriber-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Manager::removeSubscriber</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="type MongoDB\Driver\Monitoring\Subscriber" style="color:#EAB766">MongoDB\Driver\Monitoring\Subscriber</a></span> <span class="parameter" style="color:#3A95FF">\$subscriber</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Unregisters a monitoring event subscriber with this Manager.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    If <span class="parameter" style="color:#3A95FF">subscriber</span> is not already registered with this    Manager, this function is a no-op.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-manager.removesubscriber-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">subscriber</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="type MongoDB\Driver\Monitoring\Subscriber" style="color:#EAB766">MongoDB\Driver\Monitoring\Subscriber</a></span>)</dt>    <dd>     <span class="simpara">      A monitoring event subscriber to unregister with this Manager.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-manager.removesubscriber-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-manager.removesubscriber-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-manager.removesubscriber-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Manager::addSubscriber()} - Registers a monitoring event subscriber with this Manager</span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-subscriber.php" class="interfacename">MongoDB\Driver\Monitoring\Subscriber</a></span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-driver-monitoring-commandsubscriber.php" class="interfacename">MongoDB\Driver\Monitoring\CommandSubscriber</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Monitoring\removeSubscriber()} - Unregisters a monitoring event subscriber globally</span></li>   <li><a href="https://php.net/manual/zh/mongodb.tutorial.apm.php" class="xref">Application Performance Monitoring (APM)</a></li>  </ul> </div></div>
 * 
     * Unregisters a monitoring event subscriber with this Manager
     * @link https://www.php.net/manual/en/mongodb-driver-manager.removesubscriber.php
     * @since 1.10.0
     */
    final public function removeSubscriber(Subscriber $subscriber): void {}
}
